sources.factory.cod:
data Node { value::i64; next::ref<Node>; }
symbol @arena::region;
effect @arena <- region(4096u64);
proc create(value::i64) -> ref<Node> { alloc @arena Node(value, null) }

sources.valid.cod:
using symbol "std:io" @assert;
using "factory.cod" Node;
symbol from "factory.cod" @arena;
symbol @factory::proc(i64) -> ref<Node>;
effect @factory <- create;
effect @arena <- region(8192u64);
{
  let baseline = used_bytes(@arena);
  let survivor = {
    effect @arena <- region(4096u64);
    let direct = create(11);
    let current = behave @factory(13);
    behave @assert(deref(direct).value == 11);
    behave @assert(deref(current).value == 13);
    setfield(direct, next, current);
    behave @assert(deref(deref(direct).next).value == 13);
    perform @factory(7)
  };
  behave @assert(deref(survivor).value == 7);
  setfield(survivor, value, 17);
  let again = perform @factory(19);
  setfield(survivor, next, again);
  behave @assert(deref(deref(survivor).next).value == 19);
  behave @assert(used_bytes(@arena) == baseline);
};

